import reimport globfrom pathlib import Pathimport numpy as npimport pandas as pdfrom astropy.io import fits## CONFIGTARGETS_CSV = "ASTR502_Master_Target_List.csv"OUTCSV = "Carmen_master_spectra.csv"## KOA HIRES locationKOA_GLOB = "data/koa/HIRES/**/*.fits.gz"def normalize_name(s: str) -> str:    s = str(s).lower().strip()    s = s.replace("’", "").replace("'", "")    s = re.sub(r"[\s\-_]+", "", s)    return sdef build_target_lookup(targets_df: pd.DataFrame):    lookup = {}    for _, row in targets_df.iterrows():        ra = float(row["ra"]) if pd.notna(row["ra"]) else np.nan        dec = float(row["dec"]) if pd.notna(row["dec"]) else np.nan        names = []        if "hostname" in targets_df.columns and pd.notna(row["hostname"]):            names.append(str(row["hostname"]))        if "pl_name" in targets_df.columns and pd.notna(row.get("pl_name", np.nan)):            names.append(str(row["pl_name"]))        for name in names:            key = normalize_name(name)            if key:                lookup[key] = (name, ra, dec)    return lookupdef infer_target_from_text(text: str, lookup: dict) -> tuple[str, float, float]:    tnorm = normalize_name(text)    best = None    best_len = -1    for key, (name, ra, dec) in lookup.items():        if key and key in tnorm and len(key) > best_len:            best = (name, ra, dec)            best_len = len(key)    if best is None:        return ("UNKNOWN", np.nan, np.nan)    return bestdef keep_koa_file(fp: str) -> bool:    p = fp.lower()    ## Remove calibrations and non-science products    bad = [        "arc", "arcids", "bias", "dark", "flat", "trace", "lamp", "thar", "calib",        "focus", "pin", "engineering"    ]    if any(b in p for b in bad):        return False    ## Also exclude obviously non-stellar subfolders KOA uses    if "/anc/" in p or "/cal/" in p:        return False    return Truedef file_size_ok(fp: str) -> bool:    try:        return Path(fp).stat().st_size > 10_000    except Exception:        return Falsedef get_header_str(hdr, *keys, default="UNKNOWN"):    for k in keys:        try:            v = hdr.get(k, None)            if v is None:                continue            s = str(v).strip()            if s:                return s        except Exception:            pass    return defaultdef extract_header_snr(hdr) -> float:    candidates = []    for k in hdr.keys():        ku = str(k).upper()        if "SNR" in ku or ku.startswith("SN"):            try:                v = hdr[k]                if isinstance(v, (int, float, np.integer, np.floating)):                    candidates.append(float(v))            except Exception:                pass    candidates = [v for v in candidates if np.isfinite(v) and 0 < v < 1e6]    if not candidates:        return np.nan    return float(np.nanmax(candidates))def main():    targets = pd.read_csv(TARGETS_CSV)    lookup = build_target_lookup(targets)    files = sorted(set(glob.glob(KOA_GLOB, recursive=True)))    files = [f for f in files if keep_koa_file(f)]    files = [f for f in files if file_size_ok(f)]    print("Found KOA HIRES files (filtered):", len(files))    rows = []    for fp in files:        try:            with fits.open(fp) as hdul:                hdr0 = hdul[0].header            instrument = get_header_str(hdr0, "INSTRUME", "TELESCOP", default="HIRES")            obj = get_header_str(hdr0, "OBJECT", "TARGNAME", "TARGET", default="UNKNOWN")            ## Added metadata that helps pick "best" spectrum when SNR isn't in headers            exptime = hdr0.get("EXPTIME", np.nan)            mjd = hdr0.get("MJD-OBS", hdr0.get("MJD", np.nan))            dateobs = get_header_str(hdr0, "DATE-OBS", default="")            snr_hdr = extract_header_snr(hdr0)            host, ra, dec = infer_target_from_text(fp, lookup)            if host == "UNKNOWN":                host2, ra2, dec2 = infer_target_from_text(obj, lookup)                if host2 != "UNKNOWN":                    host, ra, dec = host2, ra2, dec2            rows.append(                {                    "Filename": fp,                    "Target": host,                    "RA": ra,                    "Dec": dec,                    "instrument": instrument,                    "OBJECT_hdr": obj,                    "DATE_OBS": dateobs,                    "MJD_OBS": mjd,                    "EXPTIME": exptime,                    "SNR_General": snr_hdr,                    "SNR_Li": np.nan,                    "SNR_Ha": np.nan,                    "SNR_Ca": np.nan,                    "wavelength_low": np.nan,                    "wavelength_high": np.nan,                    "note": "header_only",                }            )        except Exception as e:            rows.append(                {                    "Filename": fp,                    "Target": "UNKNOWN",                    "RA": np.nan,                    "Dec": np.nan,                    "instrument": "UNKNOWN",                    "OBJECT_hdr": "",                    "DATE_OBS": "",                    "MJD_OBS": np.nan,                    "EXPTIME": np.nan,                    "SNR_General": np.nan,                    "SNR_Li": np.nan,                    "SNR_Ha": np.nan,                    "SNR_Ca": np.nan,                    "wavelength_low": np.nan,                    "wavelength_high": np.nan,                    "note": "open_failed",                    "error": str(e),                }            )    df = pd.DataFrame(rows)    df.to_csv(OUTCSV, index=False)    print(f"Wrote {OUTCSV} with {len(df)} rows")    print("Targets top:")    print(df["Target"].value_counts().head(15).to_string())    print("Notes top:")    print(df["note"].value_counts().head(10).to_string())if __name__ == "__main__":    main()